const modules=[
 {id:'foundation',title:'编程与工程基础',tag:'准备阶段',hours:24,skills:['Python：函数、异常与模块','HTTP、JSON 与接口调用','Git、环境变量与自动化测试'],result:'交付一个能读取文件、处理异常的命令行工具。',lesson:{title:'让程序成为可以检验的工具',intro:'Agent 会调用程序来完成工作。先把一个小工具写得可靠，再让模型决定何时调用它。没有编程基础时，这一步是整个路线的起点。',concept:'函数通过输入产生输出；异常表示执行失败。把输入、输出和失败情况写清楚，后续模型调用这个函数时才有明确的边界。先掌握局部程序行为，再学习远程接口。',example:'为咨询预约系统编写一个检查函数：合法的日期返回可用时间，格式错误时返回明确的错误。不要让函数遇到任何输入都给出“预约成功”。',code:'def validate_name(name):\n    if not isinstance(name, str):\n        raise TypeError("name must be a string")\n    cleaned = name.strip()\n    if not cleaned:\n        raise ValueError("name cannot be empty")\n    return {"name": cleaned}\n\nassert validate_name(" Ada ") == {"name": "Ada"}',exercise:'运行示例，然后增加两组测试：空字符串和非字符串。解释每组测试为什么失败，并区分输入不合法和程序本身出错。',question:'一个工具收到不合法的输入时，哪种处理更适合后续 Agent 调用？',options:['返回一个看起来正常的结果','明确报告错误类型与原因','直接忽略输入并继续执行'],answer:1,explanation:'明确的失败信息让调用者决定修正输入、重试或停止。伪装成功会让后续步骤建立在错误结果上。',source:null}},
 {id:'models',title:'模型调用与结构化输出',tag:'核心基础',hours:12,skills:['消息与上下文组织','结构化输出与校验','超时、重试与成本记录'],result:'把用户需求转成经过校验的任务数据。',lesson:{title:'把自然语言变成可用的数据',intro:'用户说“帮我安排下周的咨询”，程序需要的是日期、时长和目标。模型负责理解自然语言，程序负责检查结果是否能用。',concept:'定义数据字段和允许值，要求模型按约定输出，再用程序校验。结构合法只说明格式正确，日期和业务规则仍要单独检查。',example:'预约助手提取日期、时长和用户意图。如果用户没有说时区，就把它标记为待确认信息，避免自行补出一个确定答案。',code:'task = {\n    "intent": "book_consultation",\n    "date": None,\n    "duration_minutes": 30,\n    "missing_fields": ["date", "timezone"]\n}\n\n# 业务校验：缺少关键字段时先询问用户\nif task["missing_fields"]:\n    next_step = "ask_for_details"',exercise:'设计一个“学习需求”数据结构，包含目标职业、基础、每周时间和缺失信息。准备三种不同的用户描述，手动检查提取结果。',question:'模型输出了合法 JSON，就可以直接执行预约了吗？',options:['可以，JSON 合法代表内容正确','还要校验业务规则和缺失信息','只需要确认输出足够长'],answer:1,explanation:'格式校验与业务校验解决不同问题。合法 JSON 也可能包含不存在的时间或未确认的信息。',source:0}},
 {id:'agent',title:'Agent 机制与任务分解',tag:'核心能力',hours:12,skills:['工作流与自主决策的区别','执行循环与停止条件','任务拆解与环境反馈'],result:'为一个业务任务设计可观察、可停止的执行流程。',lesson:{title:'何时需要一个 Agent？',intro:'一个预约助手需要理解需求、查询时间，并根据查询结果继续行动。先判断哪些步骤是固定的，哪些步骤需要根据反馈决定。',concept:'固定顺序可以用工作流组织。需要根据中间结果选择下一步时，可以让模型参与决策。每次动作以后，读取实际工具返回值；设置步数、时间或费用上限。',example:'查询日程返回“时间已满”，助手应该给出其他可用时间，而不是沿用最初的预约计划。最终状态要由预约工具的真实结果决定。',code:'for step in range(MAX_STEPS):\n    decision = plan(task, observations)\n    if decision.type == "finish":\n        break\n    result = run_tool(decision.tool, decision.args)\n    observations.append(result)\nelse:\n    stop_with_reason("step_budget_exhausted")\n\n# 示意伪代码；plan 和 run_tool 需要实际实现',exercise:'为“从三份文档里回答一个问题”画出流程。标记固定步骤、需要决策的步骤、失败分支和停止条件。',question:'什么信息最能帮助 Agent 判断上一步是否成功？',options:['它之前写出的执行计划','实际工具返回值与环境状态','它给出的自信程度'],answer:1,explanation:'计划表达意图，工具结果反映实际发生的事情。应根据结果决定下一步。',source:0}},
 {id:'tools',title:'工具调用与权限边界',tag:'实践模块',hours:14,skills:['工具输入和输出契约','读写权限与确认点','重复执行与幂等性'],result:'接入一个带输入校验和失败反馈的业务工具。',lesson:{title:'设计一个可靠的工具接口',intro:'模型能提出动作，工具实际执行动作。接口设计会直接影响 Agent 是否能正确使用你的系统。',concept:'工具应该有单一、清楚的职责，说明何时使用、字段意义、返回内容和失败方式。读操作与写操作分开。对于产生重复记录的操作，使用请求标识来防止重试导致重复写入。',example:'把“查找可预约时间”和“创建预约”设计成两个工具。查询不修改记录；创建需要完整字段与已确认的用户意图。',code:'{\n  "name": "find_available_slots",\n  "description": "查询指定日期的空闲时间，不创建预约",\n  "input": {"date": "YYYY-MM-DD", "timezone": "IANA timezone"},\n  "output": {"slots": [], "error": null}\n}',exercise:'为“创建预约”补全接口：必填参数、请求标识、成功返回和两种失败状态。说明工具怎样处理同一请求的再次提交。',question:'同一个创建请求在网络重试后到达两次，应该怎样处理？',options:['每次都新建一条记录','通过请求标识返回同一执行结果','让模型猜测是否已创建'],answer:1,explanation:'幂等设计使重试不会重复创建记录。实际是否创建应由存储系统确认。',source:0}},
 {id:'retrieval',title:'知识检索与有据回答',tag:'实践模块',hours:16,skills:['文档切分与检索','证据引用与缺失处理','检索质量测试'],result:'交付一个带引用、能处理证据不足的文档助手。',lesson:{title:'回答之前，先找到证据',intro:'企业知识助手要回答具体业务问题。把相关资料交给模型之前，先确定检索返回的片段确实能支持答案。',concept:'检索负责找到候选证据，生成负责组织答案。区分“没有检索到”和“资料中不存在”。记录文档版本、片段标识与来源，便于复核回答。',example:'用户询问退款期限，助手找到一份旧版规则。若无法确认当前有效版本，应明确说明版本问题，而不是把旧规定当成现行规定。',code:'question → retrieve candidates → check relevance\n         → verify document version\n         → answer with supporting references\n         → no evidence? ask or report limitation\n\n# 示意流程；检索命中不等于证据充分',exercise:'准备五份短文档和六个问题，其中两个问题无法从文档回答。检查系统能否正确引用来源，并在证据不足时停止推断。',question:'检索返回了相似度很高的片段，这代表什么？',options:['答案已被证明正确','它是候选证据，还要检查相关性和版本','可以省略来源'],answer:1,explanation:'语义相似不能证明片段支持结论。需要检查它是否回答问题，以及是否适用于当前场景。',source:0}},
 {id:'state',title:'状态管理与可靠执行',tag:'工程进阶',hours:16,skills:['显式状态与检查点','失败恢复和人工介入','会话与业务数据分离'],result:'使一个多步骤任务在中断后能够安全恢复。',lesson:{title:'让长任务可以暂停、恢复',intro:'任务可能等待用户确认，也可能在执行中断。只保存聊天记录，往往不足以回答“已经执行到哪一步”。',concept:'把当前阶段、已确认信息、工具结果和待处理动作组织成显式状态。检查点记录可恢复的位置。恢复前核对外部动作是否完成，避免重复发送或重复写入。',example:'预约已写入数据库，但发送通知失败。恢复时应该重新尝试通知，并通过预约标识读取原记录，避免再次创建预约。',code:'state = {\n    "stage": "notification_pending",\n    "booking_id": "booking_001",\n    "user_confirmed": True,\n    "notification_sent": False,\n    "retry_count": 0\n}\n# 恢复时核对真实预约记录，再执行待办动作',exercise:'为一次三步骤任务模拟中断：查询成功、写入成功、通知失败。写出检查点内容与恢复流程，并指出哪些动作不能直接重跑。',question:'恢复一个已完成写入、但通知失败的任务时，应先做什么？',options:['从头重新创建全部记录','核对已完成动作，再恢复待办步骤','删除所有状态'],answer:1,explanation:'恢复要结合持久化状态和外部系统的实际记录。重跑全部步骤可能产生重复副作用。',source:1}},
 {id:'eval',title:'评估、追踪与质量改进',tag:'工程进阶',hours:18,skills:['代表性数据集','任务结果与执行轨迹评估','回归测试与成本分析'],result:'建立一个能比较系统版本的评估报告。',lesson:{title:'如何证明你的 Agent 变好了？',intro:'一次成功演示不足以说明系统稳定。先定义任务成功的条件，再准备代表性案例，用相同标准比较不同版本。',concept:'同时检查最终结果和执行过程。正确答案可能来自错误工具或未授权动作。把正常情况、缺失信息、工具失败和边界条件加入案例集，记录成功率、失败类型与成本。',example:'预约助手有 20 个固定案例：正常预约、日期缺失、重复请求、日历超时等。一个版本虽然回答更流畅，但重复创建了预约，仍应被标记为失败。',code:'case = {\n    "input": "帮我预约咨询，但还没确定时间",\n    "expected_action": "ask_for_date",\n    "forbidden_action": "create_booking"\n}\n\n# 检查输出，也检查工具调用轨迹\n# 固定案例集用于回归，新案例用于检查泛化',exercise:'为文档助手编写 10 个评估案例，每个案例明确预期结果、证据要求和禁止行为。将错误分成检索、推理、工具执行三类。',question:'一个 Agent 最终答案正确，但调用了不该调用的写入工具，应怎样评估？',options:['只看答案，判定完全通过','结果与执行过程分别检查，标记越界行为','忽略工具调用'],answer:1,explanation:'实际交付需要同时满足任务结果与过程约束。只看最终文字会漏掉错误的外部动作。',source:2}},
 {id:'delivery',title:'部署、运营与作品交付',tag:'交付阶段',hours:16,skills:['配置、监控与版本管理','成本预算与失败兜底','作品演示与技术说明'],result:'交付一套可部署、可观测、有评估证据的 Agent 应用。',lesson:{title:'把能运行的 Demo 变成可交付的作品',intro:'交付不仅是提供一个访问链接。你需要让使用者理解它能完成什么，让维护者能判断问题出在哪里。',concept:'区分开发、测试与生产配置；在服务端管理密钥；为请求记录必要的运行信息，避免日志泄露敏感输入。给失败情况提供可理解的结果，并保留回退版本。',example:'文档助手上线后检索服务超时。页面应该显示可重试的失败状态，服务端记录失败阶段与请求标识，而不是展示一个虚构的回答。',code:'release checklist:\n  [ ] environment configured on server\n  [ ] representative evals passed\n  [ ] timeout and error paths tested\n  [ ] request budget configured\n  [ ] health checks and rollback documented\n  [ ] demo and limitations explained',exercise:'录制或撰写三段演示：正常完成任务、缺少信息、工具失败。提交部署说明和评估报告，并请他人按照说明复现。',question:'作品交付时，哪组证据最有价值？',options:['一个成功截图','可运行项目、评估报告与失败演示','只有很长的提示词'],answer:1,explanation:'这些证据分别说明作品是否可用、是否稳定，以及在异常情况下怎样表现。',source:2}}
];
const projects=[
 {id:'p1',title:'有据可查的知识助手',stage:'PROJECT 01 · 基础实战',symbol:'{↗}',desc:'围绕真实业务资料构建一个文档问答助手。它要能够引用证据，并正确处理“资料里没有答案”的情况。',checks:['准备至少 5 份有来源和版本的资料','答案能够定位到支持它的文档片段','证据不足时说明原因，不补造事实','建立至少 10 个代表性评估案例','提供运行说明、结果报告和失败演示']},
 {id:'p2',title:'可恢复的业务 Agent',stage:'PROJECT 02 · 毕业作品',symbol:'⌘',desc:'选择咨询预约、工单分流或资料研究场景，完成一个带真实工具、状态恢复和质量评估的应用。',checks:['定义工具契约、输入校验与权限边界','通过请求标识避免重复写入','模拟工具超时并验证恢复流程','同时评估最终结果与工具调用轨迹','提交可部署代码、成本说明和作品演示']}
];
const levelNames={beginner:'入门探索者',developer:'开发者转型',practitioner:'从业者进阶'};
const goalNames={career:'入行就业 · 完成作品集',product:'产品开发 · 做出可用的应用',advanced:'能力进阶 · 可靠交付'};
const storageKey='rolecraft-v1';
const curriculum=typeof curriculumData==='undefined'?null:curriculumData;
const labels={home:'首页',path:'学习路线',learn:'课程学习',questions:'题库浏览',review:'复习',check:'检验学习结果',settings:'个人设置',records:'学习记录','history-home':'历史学习概览','history-path':'历史职业路线','projects-history':'历史项目记录',book:'历史教材与测验',projects:'项目工坊',standards:'能力标准',curriculum:'课程地图',reflections:'复盘中心',sources:'知识来源',creation:'0→1 产品路线','product-review':'产品达标复盘',generation:'单章生成'};
const roles=['项目经理','产品经理','课程架构师','设计师','软件工程师','测试工程师'];
const deliverables=[{id:'product-standard',title:'产品要求',role:'产品经理',version:'2026-10-10'},{id:'curriculum-standard',title:'教学标准与课程地图',role:'课程架构师',version:'curriculum-draft-0.2'},{id:'design-standard',title:'页面与复盘交互规范',role:'设计师',version:'2026-10-10'},{id:'application',title:'职造本地网站',role:'软件工程师',version:'local-mvp-0.6-textbook-pilot'},{id:'qa-review',title:'独立质量检查报告',role:'测试工程师',version:'2026-10-10'},{id:'team-plan',title:'团队计划与交接记录',role:'项目经理',version:'2026-10-10'}];
const reflectionFields=[['goal','目标与评价标准'],['evidence','证据链接或文字'],['result','实际结果'],['gap','差距与失败分类'],['cause','原因假设与未知'],['improvement','改进动作与取舍'],['assignee','改进责任人'],['plannedDate','计划日期'],['retestMethod','复验方法'],['retestResult','复验结果']];
const selfStatuses=['待改进','已改进','待复验'];
const textValue=(v,max=12000)=>typeof v==='string'?v.slice(0,max):'';
const objectValue=v=>v&&typeof v==='object'&&!Array.isArray(v)?v:{};
function normalizeReflection(raw){const r=objectValue(raw);const kind=r.kind==='employee'?'employee':'learning';const type=kind==='employee'?'deliverable':['chapter','exercise','project'].includes(r.type)?r.type:'chapter';const list=type==='deliverable'?deliverables:type==='project'?projects:modules;const artifactId=list.some(a=>a.id===r.artifactId)?r.artifactId:'';const out={id:textValue(r.id,200),kind,type,artifactId,version:textValue(r.version,200),ownerRole:roles.includes(r.ownerRole)?r.ownerRole:'',selfStatus:selfStatuses.includes(r.selfStatus)?r.selfStatus:'待改进',independentReview:'未独立审核',createdAt:textValue(r.createdAt,100),updatedAt:textValue(r.updatedAt,100)};reflectionFields.forEach(([key])=>out[key]=textValue(r[key]));return out;}
const currentProductVersion='local-workbench-0.14-dialog';
const requiredBenchmarkFields=Object.freeze(['source','sourceType','date','version','task','sample','resourceConstraints','metric','targetThreshold','comparisonMethod','actualResults']);
function validProductStandard(d){return Boolean(d?.schemaVersion==='1.0'&&typeof d.standardVersion==='string'&&d.standardVersion.trim()&&d.scope==='formal_learning_product'&&Array.isArray(d.gates)&&d.gates.length===8&&new Set(d.gates.map(g=>g.id)).size===8&&d.gates.every(g=>g&&typeof g.id==='string'&&g.id&&g.required===true&&typeof g.label==='string'&&typeof g.criterion==='string'&&typeof g.owner==='string'&&Array.isArray(g.evidenceRequired))&&Array.isArray(d.benchmarkFields)&&d.benchmarkFields.length===requiredBenchmarkFields.length&&new Set(d.benchmarkFields).size===requiredBenchmarkFields.length&&requiredBenchmarkFields.every(k=>d.benchmarkFields.includes(k))&&Array.isArray(d.benchmarkSourceTypes)&&d.conclusions?.not_met&&d.conclusions?.insufficient&&d.conclusions?.met_within_scope&&d.gateStatuses?.fail&&d.gateStatuses?.insufficient&&d.gateStatuses?.pass&&d.decisionRules&&d.initialAssessment&&Array.isArray(d.evidenceTypes));}
const productStandard=typeof productGatesData!=='undefined'&&validProductStandard(productGatesData)?productGatesData:null;
const creationPath=typeof creationPathData!=='undefined'&&Array.isArray(creationPathData?.stages)&&creationPathData.stages.length===7&&typeof creationPathData.version==='string'&&Array.isArray(creationPathData.benchmarkSources)&&creationPathData.evaluationPolicy&&creationPathData.retrospectiveTemplate&&creationPathData.stages.every(s=>s&&typeof s.id==='string'&&typeof s.title==='string'&&['objectives','prerequisites','deliverables','retrospectiveQuestions','moduleIds','benchmarkSourceIds'].every(k=>Array.isArray(s[k]))&&s.evaluation&&['success','failure','insufficient'].every(k=>typeof s.evaluation[k]==='string'))?creationPathData:null;
const independentAudits=typeof productAuditData==='undefined'?{reports:[]}:productAuditData;
const productScopes={formal_learning_product:'正式职业学习系统',learner_product:'学习者行业产品（门槛适用性待专业确认）',static_prototype:'静态原型（八门槛自评不等于静态功能QA）'};
const baselineLabels={source:'基线来源',sourceType:'来源类型',date:'基线日期',version:'基线版本',task:'比较任务',sample:'样本',resourceConstraints:'资源约束',metric:'比较指标',targetThreshold:'预定阈值（结果之前定义）',comparisonMethod:'比较方法',actualResults:'基线实际结果'};
const productEvidenceTypeLabels={self_report:'自述',learning_record:'学习记录',project_artifact:'项目产物',automated_evaluation:'自动评估记录（待核实）',independent_qa:'独立QA来源线索（待核实）',professional_review:'专业评审来源线索（待核实）',user_validation:'用户验证记录（待核实）'};
const sourceTypeLabels={industry_product:'行业产品',research:'研究',professional_review:'专业评审'};
const productLabels={productGoal:'产品目标',artifactId:'产物 ID',artifactVersion:'产物版本',scope:'评价范围',stageId:'关联创造阶段',actualResults:'整体实际结果',gap:'差距',cause:'原因',causeType:'原因性质',owner:'责任人',nextAction:'下一步行动',retestConditions:'复验条件',retestMethod:'复验方法',retestResult:'复验结果'};
function normalizeProductReview(raw){const r=objectValue(raw),baseline=objectValue(r.baseline),gates=objectValue(r.gateEvidence);const out={id:textValue(r.id,200),standardVersion:textValue(r.standardVersion,200),createdAt:textValue(r.createdAt,100),updatedAt:textValue(r.updatedAt,100),independentReview:'未独立审核',professionalReview:'未专业审核',advancedStatus:'行业先进性未验证'};for(const key of Object.keys(productLabels))out[key]=textValue(r[key]);out.scope=Object.hasOwn(productScopes,out.scope)?out.scope:'';out.stageId=creationPath?.stages.some(s=>s.id===out.stageId)?out.stageId:'';out.causeType=['fact','hypothesis','unknown'].includes(out.causeType)?out.causeType:'unknown';out.baseline={};for(const key of productStandard?.benchmarkFields||Object.keys(baselineLabels))out.baseline[key]=textValue(baseline[key]);if(!Object.hasOwn(sourceTypeLabels,out.baseline.sourceType))out.baseline.sourceType='';out.gateEvidence=Object.create(null);for(const gate of productStandard?.gates||Object.keys(gates).map(id=>({id}))){const g=objectValue(gates[gate.id]);out.gateEvidence[gate.id]={status:['fail','insufficient','pass'].includes(g.status)?g.status:'insufficient',evidence:textValue(g.evidence),actualResults:textValue(g.actualResults),evidenceType:(productStandard?.evidenceTypes||[]).includes(g.evidenceType)?g.evidenceType:'self_report'};}out.selfConclusion=productDecision(out);return out;}
function hasKnownEvidence(v){return typeof v==='string'&&v.trim()&&!['待确认','未知','未提供','未验证','证据不足','未复验','unknown','null','n/a'].includes(v.trim().toLowerCase());}
function productDecision(raw){if(!productStandard)return 'insufficient';const r=objectValue(raw),gates=objectValue(r.gateEvidence),required=productStandard.gates.filter(g=>g.required);if(required.some(g=>gates[g.id]?.status==='fail'))return 'not_met';if(!required.length||r.standardVersion!==productStandard.standardVersion)return 'insufficient';if(!Object.hasOwn(productScopes,r.scope)||!['productGoal','artifactId','artifactVersion','scope'].every(k=>hasKnownEvidence(r[k])))return 'insufficient';if(!required.every(g=>gates[g.id]?.status==='pass'&&hasKnownEvidence(gates[g.id].evidence)&&hasKnownEvidence(gates[g.id].actualResults)))return 'insufficient';const b=objectValue(r.baseline);if(!productStandard.benchmarkFields.every(k=>hasKnownEvidence(b[k]))||!productStandard.benchmarkSourceTypes.includes(b.sourceType))return 'insufficient';return 'met_within_scope';}
function normalizeProductRecords(raw){const ids=new Set();return (Array.isArray(raw)?raw:[]).map(normalizeProductReview).filter(r=>r.id&&!ids.has(r.id)&&ids.add(r.id));}
const defaults=()=>({profile:{level:'beginner',goal:'career',hours:8},passed:[],checks:{},notes:{},lastLesson:'foundation',reflections:[],reflectionDraft:null,productReviews:[],productReviewDraft:null});
function normalizeState(raw){const r=objectValue(raw),p=objectValue(r.profile),checks=objectValue(r.checks),notes=objectValue(r.notes);const out=defaults();out.profile={level:levelNames[p.level]?p.level:'beginner',goal:goalNames[p.goal]?p.goal:'career',hours:Math.min(20,Math.max(3,Number(p.hours)||8))};out.passed=[...new Set((Array.isArray(r.passed)?r.passed:[]).filter(id=>modules.some(m=>m.id===id)))];projects.forEach(p=>{out.checks[p.id]=[...new Set((Array.isArray(checks[p.id])?checks[p.id]:[]).filter(i=>Number.isInteger(i)&&i>=0&&i<p.checks.length))];out.notes[p.id]=textValue(notes[p.id]);});out.lastLesson=modules.some(m=>m.id===r.lastLesson)?r.lastLesson:'foundation';const ids=new Set();out.reflections=(Array.isArray(r.reflections)?r.reflections:[]).map(normalizeReflection).filter(r=>r.id&&!ids.has(r.id)&&ids.add(r.id));if(r.reflectionDraft){out.reflectionDraft={...normalizeReflection(r.reflectionDraft),dirty:Boolean(r.reflectionDraft.dirty)};}out.productReviews=normalizeProductRecords(r.productReviews);if(r.productReviewDraft)out.productReviewDraft={...normalizeProductReview(r.productReviewDraft),dirty:Boolean(r.productReviewDraft.dirty)};return out;}
let state=defaults(),storageAvailable=true,persistencePending=false,saveMessage='记录保存在当前浏览器；不跨设备同步。',saveTone='neutral';
try{const raw=localStorage.getItem(storageKey);if(raw!==null)state=normalizeState(JSON.parse(raw));}catch{storageAvailable=false;saveTone='error';saveMessage='无法读取本地记录或数据损坏，已使用默认档案；当前输入仍可导出。'}
function readLocation(){const parts=location.hash.slice(1).split('?')[0].split('/');const v=Object.keys(labels).includes(parts[0])?parts[0]:'home';return{view:v,target:parts[1]||'',chapter:parts[2]||'',source:parts[3]||''};}
let view=readLocation().view;let selected=modules.some(m=>m.id===readLocation().target)?readLocation().target:readLocation().target==='sample'&&modules.some(m=>m.id===readLocation().chapter)?readLocation().chapter:state.lastLesson;if(typeof textbookSetLocation==='function')textbookSetLocation(readLocation());let selectedModule=curriculum?.modules.some(m=>m.id===readLocation().target)?readLocation().target:'';let quizChoice=null,quizResult=null;
const app=document.getElementById('app');
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function updateSaveStatus(){const el=document.getElementById('save-status');if(!el)return;el.textContent=saveMessage;el.classList.toggle('error',saveTone==='error');el.setAttribute('role',saveTone==='error'?'alert':'status');}
function save(options={}){persistencePending=true;const snapshot={...state};if(options.commitReflection&&state.reflectionDraft)snapshot.reflectionDraft={...state.reflectionDraft,dirty:false};if(options.commitProductReview&&state.productReviewDraft)snapshot.productReviewDraft={...state.productReviewDraft,dirty:false};try{localStorage.setItem(storageKey,JSON.stringify(snapshot));if(options.commitReflection&&state.reflectionDraft)state.reflectionDraft.dirty=false;if(options.commitProductReview&&state.productReviewDraft)state.productReviewDraft.dirty=false;persistencePending=false;storageAvailable=true;saveTone='success';saveMessage='已保存在当前浏览器 · '+new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'});updateSaveStatus();return true;}catch{storageAvailable=false;saveTone='error';saveMessage='保存失败：当前输入仍在本页面内存中。请导出学习计划／学习员工复盘／产品复盘（含草稿），刷新或关闭前保留文件。';updateSaveStatus();toast('浏览器无法保存；请导出当前记录。');return false;}}
function route(){const ids=state.profile.level==='beginner'?modules.map(m=>m.id):state.profile.level==='developer'?modules.slice(1).map(m=>m.id):['eval','state','tools','retrieval','delivery'];return ids.map(id=>modules.find(m=>m.id===id))}
function plannedHours(){return route().reduce((s,m)=>s+m.hours,0)}
function nextModule(){return route().find(m=>!state.passed.includes(m.id))||route()[0]}
function title(eyebrow,name,desc,button=true){return `<div class="page-title"><div><span class="eyebrow">${eyebrow}</span><h1>${name}</h1><p>${desc}</p></div>${button?'<button class="outline" data-action="profile">调整学习档案 ↗</button>':''}</div>`}
function progress(){const r=route();return Math.round(r.filter(m=>state.passed.includes(m.id)).length/r.length*100)}
function rows(list){return list.map((m,i)=>`<div class="module-row ${nextModule().id===m.id?'current':''}"><span class="number">${String(i+1).padStart(2,'0')}</span><div class="module-body"><h3>${m.title}</h3><p>${m.skills.slice(0,2).join(' · ')}</p></div><span class="badge ${state.passed.includes(m.id)?'green':''}">${state.passed.includes(m.id)?'测验通过':m.hours+' 小时'}</span><button data-lesson="${m.id}" aria-label="学习${m.title}">↗</button></div>`).join('')}
function home(){const n=nextModule();return title('BUILD YOUR NEXT CHAPTER','从这里，走向你的新职业。','你的目标是 Agent 开发者。每一步学习，都通向一个可以展示的成果。')+`<section class="hero"><div><span class="eyebrow">AGENT DEVELOPER · 职业学习路线</span><h2>学会构建 Agent，<br>也学会<em>把它交付。</em></h2><p>从原理理解到工程实践，用适合你的教材、练习和项目，逐步建立独立解决问题的能力。</p><button class="primary" data-lesson="${n.id}">${state.passed.length?'继续学习':'开始第一课'} <span>→</span></button></div><div class="hero-art" aria-hidden="true"><div class="orbit"><span class="orbit-label a">LEARN</span><span class="orbit-label b">BUILD</span><span class="orbit-label c">VERIFY</span><div class="core">&lt;/&gt;</div></div></div></section><div class="stats"><div class="stat"><div class="stat-label">你的学习起点 <span>◈</span></div><strong style="font-size:20px">${levelNames[state.profile.level]}</strong><p>${goalNames[state.profile.goal]}</p></div><div class="stat"><div class="stat-label">路线参考时长 <span>◷</span></div><strong>${Math.ceil(plannedHours()/state.profile.hours)}<small>周</small></strong><p>按每周 ${state.profile.hours} 小时估算，非效果承诺</p></div><div class="stat"><div class="stat-label">阶段测验 <span>✓</span></div><strong>${route().filter(m=>state.passed.includes(m.id)).length}<small>/ ${route().length} 已通过</small></strong><p>测验只验证概念理解</p></div><div class="stat"><div class="stat-label">实践作品 <span>◇</span></div><strong>2<small>个项目</small></strong><p>从知识助手到业务 Agent</p></div></div><div class="two-col"><div><div class="section-title"><h2>你的学习路线</h2><button class="text-link" data-view="path">查看全部 ↗</button></div><div class="card"><div class="section-title"><span class="note">${route().length} 个阶段 · 先学基础，再验证交付</span><span class="badge green">${progress()}% 测验通过</span></div>${rows(route().slice(0,4))}</div><div class="info-banner section-gap">这是一条起始路线。概念测验帮助发现理解缺口；真实能力还需要通过项目运行、外部评审与工作实践验证。</div></div><div class="right-col"><section><div class="section-title"><h2>把知识变成作品</h2><span class="text-link">↗</span></div><div class="card"><span class="eyebrow">LEARNING BY BUILDING</span><div class="project-preview"><span class="tag">你的第一个项目</span><h3>有据可查的<br>知识助手</h3><p>找到证据，组织答案，让每一次回答都有依据。</p><button data-view="projects">进入项目工坊 →</button></div></div></section><section class="section-gap"><div class="section-title"><h2>知识有出处</h2><button class="text-link" data-view="sources">全部 ↗</button></div><div class="card">${sources.slice(0,2).map(s=>`<div class="source-item"><span>↗</span><div><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title}</a><p>${s.org}</p></div></div>`).join('')}<p class="note">官方资料作为参考；课程内容为教学整理，尚未经行业专家审定。</p></div></section></div></div>`}
function pathPage(){return title('A PATH THAT FITS YOU','先找到起点，再一步一步前进。',`${levelNames[state.profile.level]} · 每周 ${state.profile.hours} 小时 · ${goalNames[state.profile.goal]}`)+`<div class="info-banner">${state.profile.level==='beginner'?'先补齐编程和接口基础，再进入 Agent 实践。':state.profile.level==='developer'?'利用已有编程基础，从模型调用进入 Agent 工程。':'从评估与可靠性切入；基础教材仍可在“我的教材”中查阅。'} ${state.profile.goal==='product'?'项目建议围绕你自己的业务问题展开。':state.profile.goal==='career'?'最终交付作品、运行说明与评估报告，作为作品集材料。':'把失败恢复、成本和回归测试作为重点。'} 路线由预设规则组合，尚未使用 AI 诊断。</div>${route().map((m,i)=>`<article class="card path-card"><span class="number">${String(i+1).padStart(2,'0')}</span><div><span class="eyebrow">${m.tag.toUpperCase()} · ${m.hours} 小时</span><h3>${m.title}</h3><p>${m.result}</p><ul>${m.skills.map(s=>`<li>${s}</li>`).join('')}</ul><span class="badge ${state.passed.includes(m.id)?'green':''}">${state.passed.includes(m.id)?'概念测验已通过':'待学习与实践'}</span></div><button class="outline" data-lesson="${m.id}">查看教材 →</button></article>`).join('')}`}
function bookPage(){if(typeof textbookPage==='function'&&textbookReader.mode!=='sample')return '<div class="lw-history-notice"><strong>这里是保留的历史教材</strong><p>当前 v12 三十篇教材已接入学习工作台。历史稿和测验仍可查看，不与新版正文混用。</p><a class="primary" href="#learn/agent/00-learning-route">阅读当前教材 →</a></div>'+textbookPage();return sampleBookPage();}
function sampleBookPage(){const m=modules.find(m=>m.id===selected)||nextModule();const l=m.lesson;return title('YOUR PERSONAL HANDBOOK','理解一个概念，动手验证一次。','历史短示例 sample-0.1 · 原概念测验与复盘保留，不代表已掌握新版正文',false)+`<div class="action-row"><button class="primary" data-textbook-chapter="c01">阅读新版十二章教材</button></div><div class="book-layout"><aside class="card book-nav" aria-label="教材章节">${modules.map((x,i)=>`<button data-lesson="${x.id}" class="${x.id===m.id?'active':''}" ${x.id===m.id?'aria-current="page"':''}>${String(i+1).padStart(2,'0')} &nbsp; ${x.title}<small>${state.passed.includes(x.id)?'✓ 概念测验通过':'教材 + 练习 + 测验'}</small></button>`).join('')}</aside><article class="card lesson"><span class="eyebrow">${m.tag} · 教材示例</span><h2>${l.title}</h2><p>${l.intro}</p><div class="callout"><strong>这一课的目标</strong><br>${m.result}</div><h3>01 · 理解核心概念</h3><p>${l.concept}</p><h3>02 · 放进一个真实场景</h3><p>${l.example}</p><pre><code>${escapeHTML(l.code)}</code></pre><div class="action-row"><button class="outline" data-reflect="chapter" data-artifact="${m.id}">记录教材复盘</button><button class="outline" data-reflect="exercise" data-artifact="${m.id}">记录练习复盘</button><button class="outline" data-view="curriculum">查看课程地图</button></div><h3>03 · 亲手完成一次练习</h3><p>${l.exercise}</p><p class="note">练习代码请在自己的开发环境运行。此原型不执行代码，也不自动判断作品质量。</p>${l.source!==null?`<p class="note">参考资料：<a href="${sources[l.source].url}" target="_blank" rel="noopener noreferrer">${sources[l.source].title}</a> · 原型资料标签日期 2026.10.10（未逐条核验）</p>`:'<p class="note">本章为基础教学示例；运行前请自行检查环境。</p>'}<section class="quiz"><span class="eyebrow">CHECK YOUR UNDERSTANDING</span><h3>${l.question}</h3>${l.options.map((o,i)=>`<button class="quiz-option ${quizChoice===i?'selected':''}" data-choice="${i}" aria-pressed="${quizChoice===i}">${String.fromCharCode(65+i)}. ${o}</button>`).join('')}${quizResult!==null?`<div class="quiz-feedback ${quizResult?'':'wrong'}" role="status">${quizResult?'✓ 回答正确，已记录本章测验通过。':'再想一想。'} ${l.explanation}</div>`:''}<div class="lesson-bottom"><button class="primary" data-action="quiz" ${quizChoice===null?'disabled style="opacity:.45;cursor:not-allowed"':''}>检查答案 →</button><button class="outline" data-view="projects">把知识用到项目中 ↗</button></div></section></article></div>`}
function projectsPage(){return title('PROOF OF YOUR SKILLS','用作品，让能力看得见。','检查项由你自行确认。提交真实作品并接受评审，才能验证实际交付能力。',false)+`<div class="info-banner">工坊保存项目检查项和作品备注，不进行 AI 批改，也不会授予职业资格。请在备注中记录仓库链接、运行结果和待解决的问题。</div><div class="projects-grid">${projects.map(p=>{const checks=Array.isArray(state.checks[p.id])?state.checks[p.id]:[];return `<article class="card project-card"><div class="project-icon">${p.symbol}</div><span class="eyebrow">${p.stage}</span><h2>${p.title}</h2><p>${p.desc}</p><div class="mini-progress"><span style="width:${checks.length/p.checks.length*100}%"></span></div><p class="note">${checks.length} / ${p.checks.length} 项自查完成</p>${p.checks.map((c,i)=>`<label class="check-row"><input type="checkbox" data-project="${p.id}" data-check="${i}" ${checks.includes(i)?'checked':''}><span>${c}</span></label>`).join('')}<label for="note-${p.id}" class="note">作品链接与实践记录（仅保存在当前浏览器）</label><textarea id="note-${p.id}" data-note="${p.id}" placeholder="仓库或演示链接、评估结果、遇到的问题…">${escapeHTML(state.notes[p.id]||'')}</textarea><div class="action-row"><button class="outline" data-reflect="project" data-artifact="${p.id}">记录作品复盘</button><button class="outline" data-view="standards">查看证据量规</button></div><button class="outline" data-save-note="${p.id}" style="margin-top:12px">保存实践记录</button></article>`}).join('')}</div>`}
function sourcesPage(){return title('EVIDENCE BEFORE CONFIDENCE','让每一次学习，都有据可查。','优先使用官方技术资料；通过版本记录追踪知识变化。',false)+`<div class="info-banner">“行业先进水平”需要持续的资料更新、真实项目测试和专业评审共同支撑。当前是人工整理的课程示例，尚未接入自动检索、教材生成或专家审核。</div>${sources.map((s,i)=>`<article class="card source-card"><span class="number">${String(i+1).padStart(2,'0')}</span><div><span class="eyebrow">${s.org}</span><h2>${s.title}</h2><p>${s.desc}</p><a href="${s.url}" target="_blank" rel="noopener noreferrer">阅读官方原文 ↗</a><p class="note">来源类型：官方资料 · 原型标签日期：2026.10.10（未逐条核验） · 课程版本：v0.1</p></div></article>`).join('')}<div class="card"><h3>正式教材的质量流程</h3><p class="note">职业能力定义 → 来源收集与版本核对 → 课程编排 → 按章节生成 → 示例运行与事实检查 → 教学及行业评审 → 发布 → 根据学习表现更新。</p><p class="note">正式系统应分别记录“已生成”“事实核对通过”“示例测试通过”“专家审核通过”，让学习者了解每章的审核状态。</p></div>`}
function listHTML(items){return '<ul>'+items.map(i=>'<li>'+escapeHTML(i)+'</li>').join('')+'</ul>';}
function moduleLink(id){const m=curriculum?.modules.find(m=>m.id===id);return m?`<button class="module-link" data-module="${escapeHTML(id)}">${escapeHTML(id.toUpperCase())} · ${escapeHTML(m.title)}</button>`:'';}
function sourceLinks(ids){return (ids||[]).map(id=>{const s=curriculum.sources.find(s=>s.id===id);return s?`<a href="${escapeHTML(s.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(s.title)} · ${escapeHTML(s.typeLabel)}</a>`:'';}).join('<br>');}
function curriculumNotice(){return `<div class="info-banner"><strong>${escapeHTML(curriculum.status)} · ${escapeHTML(curriculum.version)}</strong><p>${escapeHTML(curriculum.fullTextbookStatus)}。规划覆盖不代表完整教材、职业达标或录用保证。</p><p>来源页面访问日期：${escapeHTML(curriculum.updatedAt)}；专家审核：${escapeHTML(curriculum.expertReview)}。事实核对、示例测试和教学审核未实施。</p></div>`;}
function standardsPage(){if(!curriculum)return title('STANDARD','能力数据未加载','请先加载 curriculum-data.js。',false);return title('EVIDENCE OF CAPABILITY','能力标准','生产级 Agent 应用工程 · 能力标准草案，专家审核未完成',false)+curriculumNotice()+`<section class="card"><h2>${escapeHTML(curriculum.benchmark.title)}</h2><p>${escapeHTML(curriculum.benchmark.aspiration)}</p><p>${escapeHTML(curriculum.benchmark.basis)}</p>${listHTML(curriculum.benchmark.limits)}<div class="evidence-strip"><span>学习记录：仅记录概念题</span><span>作品证据：用户自查</span><span>自动评估：未实施</span><span>独立审核：未实施</span></div></section><div class="level-grid section-gap">${curriculum.levels.map(l=>`<section class="card"><h2>${escapeHTML(l.title)}层</h2><p>${escapeHTML(l.outcome)}</p><p>深度：${escapeHTML(l.depth)}</p><p>证据门槛：${escapeHTML(l.gate)}</p></section>`).join('')}</div><section class="section-gap"><h2>七能力域 × 四层级</h2><p class="muted">规划覆盖7域，现有教材教学覆盖尚未验证；关联为教学规划，未安排不等于能力缺失，模块出现不等于已掌握。</p>${curriculum.competencies.map(c=>`<article class="card competency-card"><h3>${escapeHTML(c.title)}</h3><p>${escapeHTML(c.description)}</p><div class="matrix-levels">${curriculum.levels.map(l=>{const related=curriculum.modules.filter(m=>m.level===l.id&&m.competencyIds.includes(c.id));return `<section><h4>${escapeHTML(l.title)}</h4>${related.length?related.map(m=>moduleLink(m.id)).join(''):'<p>本层级未安排</p>'}</section>`;}).join('')}</div><details><summary>所需作品证据与来源</summary>${listHTML([...new Set(curriculum.modules.filter(m=>m.competencyIds.includes(c.id)).flatMap(m=>m.evidence))])}${sourceLinks(c.sourceIds)}</details></article>`).join('')}</section><section class="card section-gap"><h2>0—3 项目证据量规</h2><p>${escapeHTML(curriculum.rubric.status)} · 教学推导，尚未专家校准</p>${listHTML(curriculum.rubric.scoreScale.map(s=>s.score+' 分：'+s.label))}<div class="rubric-grid">${curriculum.rubric.dimensions.map(d=>`<article><h3>${escapeHTML(d.title)}</h3><p>${escapeHTML(d.evidence)}</p></article>`).join('')}</div><p>${escapeHTML(curriculum.rubric.gate)}</p><p>门槛来源：${escapeHTML(curriculum.rubric.thresholdOrigin)}</p>${curriculum.projects.map(p=>`<details><summary>${escapeHTML(p.title)} · ${escapeHTML(p.type)}</summary><p>${escapeHTML(p.status)}</p><h3>提交证据</h3>${listHTML(p.deliverables)}<h3>适用量规</h3>${listHTML(p.rubricDimensionIds.map(id=>curriculum.rubric.dimensions.find(d=>d.id===id).title))}<h3>关键检查</h3>${listHTML(p.criticalChecks)}<button class="outline" data-reflect="project" data-artifact="${escapeHTML(p.id)}">记录作品复盘</button></details>`).join('')}</section><section class="card section-gap"><h2>真实参考来源与适用边界</h2>${curriculum.sources.map(s=>`<article class="benchmark-source"><h3><a href="${escapeHTML(s.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(s.title)}</a></h3><p>${escapeHTML(s.typeLabel)} · ${escapeHTML(s.organization)} · 访问日期 ${escapeHTML(s.accessedAt)} · 发布日期 ${escapeHTML(s.publishedAt||'未知')}</p><p>原文位置：${escapeHTML(s.sections.join(' / '))}</p>${listHTML(s.supports)}<p>${escapeHTML(s.limits)}</p></article>`).join('')}</section>`;}
function curriculumPage(){if(!curriculum)return title('CURRICULUM','课程数据未加载','请先加载 curriculum-data.js。',false);return title('MAP YOUR LEARNING','课程地图',`${curriculum.competencies.length} 能力域／${curriculum.levels.length} 层级／${curriculum.modules.length} 模块；现有 ${modules.length} 章为短示例`,false)+curriculumNotice()+`<section class="card"><h2>清晰、广、精的教学要求</h2>${listHTML(curriculum.qualityRules.map(r=>r.title+'：'+r.measure))}<button class="outline" data-view="standards">查看能力关联与评价量规</button></section>`+curriculum.levels.map(l=>`<section class="section-gap"><h2>${escapeHTML(l.title)}层 · ${escapeHTML(l.outcome)}</h2>${curriculum.modules.filter(m=>m.level===l.id).map(m=>`<article class="card curriculum-module" id="module-${escapeHTML(m.id)}"><span class="state-label">课程地图草案 · 专家审核未完成</span><h3 id="module-title-${escapeHTML(m.id)}" tabindex="-1">${escapeHTML(m.id.toUpperCase())} · ${escapeHTML(m.title)}</h3><p>能力域：${escapeHTML(m.competencyIds.map(id=>curriculum.competencies.find(c=>c.id===id).title).join('、'))}</p><h4>可观察目标</h4>${listHTML(m.objectives)}<div class="prerequisites"><strong>先修：</strong>${m.prerequisites.length?m.prerequisites.map(moduleLink).join(''):'无模块先修；起点需根据实际证据确认'}</div><h4>产物证据</h4>${listHTML(m.evidence)}<h4>验证方式</h4>${listHTML(m.validation)}<details><summary>深度、九项教材结构与来源</summary><p>深度：${escapeHTML(m.depth)}</p><ol>${curriculum.chapterStructure.sections.map(s=>`<li><strong>${escapeHTML(s.title)}</strong>：${escapeHTML(s.required)}</li>`).join('')}</ol>${sourceLinks(m.sourceIds)}<p>${escapeHTML(m.sourceScope)}</p><p>事实核对：未实施 · 示例测试：未实施 · 教学审核：未实施 · 专家审核：未完成</p></details><div class="action-row">${m.existingChapterIds.length?m.existingChapterIds.map(id=>`<button class="outline" data-lesson="${escapeHTML(id)}">查看短教材示例：${escapeHTML(modules.find(x=>x.id===id)?.title||id)}</button>`).join(''):'<p>完整教材待编写</p>'}</div>${m.existingChapterIds.length?'<p class="muted">短示例不代表本模块完整教材已完成；完整教材待编写。</p>':''}</article>`).join('')}</section>`).join('');}
function reflectionOptions(kind,type){return kind==='employee'?deliverables:type==='project'?projects:modules;}
function artifactTitle(r){return reflectionOptions(r.kind,r.type).find(a=>a.id===r.artifactId)?.title||'尚未选择产物';}
const typeNames={chapter:'教材',exercise:'练习',project:'作品',deliverable:'电子员工交付物'};
function fieldInput(key,label,r){const value=escapeHTML(r[key]||'');const required=['goal','result'].includes(key);return `<label for="reflection-${key}">${escapeHTML(label)}${required?' <span>（必填）</span>':''}</label>${key==='plannedDate'?`<input type="date" name="${key}" id="reflection-${key}" value="${value}">`:key==='assignee'?`<input name="${key}" id="reflection-${key}" value="${value}" maxlength="12000">`:`<textarea name="${key}" id="reflection-${key}" maxlength="12000" ${required?'required':''} placeholder="${key==='evidence'?'可记录证据不足；链接仅作为文字保存':key==='cause'?'原因待确认；区分假设与已验证事实':key==='retestResult'?'未复验':''}">${value}</textarea>`}`;}
function reflectionsPage(){const r=state.reflectionDraft;return title('IMPROVE WITH EVIDENCE','复盘中心','学习与电子员工产物分别复盘；自述不代表独立审核',false)+`<div class="info-banner">多条记录保存在当前浏览器，可导出全部记录及当前草稿。概念题、作品自查和复验自述均不能转为职业达标。${curriculum?escapeHTML(curriculum.reflection.minimum):''}</div><div class="action-row"><button class="primary" data-action="new-reflection">新建复盘</button><button class="outline" data-action="export-reflections">导出全部复盘（含草稿）</button></div>${r?`<section class="card section-gap"><h2>${r.id?'编辑复盘':'新建复盘'}</h2><p id="reflection-feedback" role="status">${r.dirty?'未提交的草稿已保留；请完成后保存为记录。':'编辑不会覆盖其他记录。'}</p><form id="reflection-form" novalidate><fieldset><legend>① 对象与版本</legend><label for="reflection-kind">复盘类型</label><select id="reflection-kind" name="kind"><option value="learning" ${r.kind==='learning'?'selected':''}>学习复盘</option><option value="employee" ${r.kind==='employee'?'selected':''}>电子员工产物复盘</option></select><label for="reflection-type">对象类型</label><select id="reflection-type" name="type">${(r.kind==='employee'?['deliverable']:['chapter','exercise','project']).map(t=>`<option value="${t}" ${r.type===t?'selected':''}>${typeNames[t]}</option>`).join('')}</select><label for="reflection-artifactId">产物（必填）</label><select id="reflection-artifactId" name="artifactId" required><option value="">请选择产物</option>${reflectionOptions(r.kind,r.type).map(a=>`<option value="${escapeHTML(a.id)}" ${r.artifactId===a.id?'selected':''}>${escapeHTML(a.title)}</option>`).join('')}</select><label for="reflection-version">产物版本</label><input id="reflection-version" name="version" maxlength="200" value="${escapeHTML(r.version)}"><div id="role-field" ${r.kind!=='employee'?'hidden':''}><label for="reflection-ownerRole">产物责任岗位</label><select id="reflection-ownerRole" name="ownerRole"><option value="">请选择责任岗位</option>${roles.map(role=>`<option ${r.ownerRole===role?'selected':''}>${role}</option>`).join('')}</select></div></fieldset><fieldset><legend>② 目标与实际对照</legend>${reflectionFields.slice(0,5).map(([key,label])=>fieldInput(key,label,r)).join('')}</fieldset><fieldset><legend>③ 改进行动与复验</legend>${reflectionFields.slice(5).map(([key,label])=>fieldInput(key,label,r)).join('')}<label for="reflection-selfStatus">自述状态</label><select name="selfStatus" id="reflection-selfStatus">${selfStatuses.map(s=>`<option ${s===r.selfStatus?'selected':''}>${s}</option>`).join('')}</select><p class="state-label">独立审核状态：未独立审核（只读）</p></fieldset><div class="action-row"><button class="primary" type="submit">保存复盘记录</button><button class="outline" type="button" data-action="export-reflections">导出当前草稿与记录</button><button class="outline" type="button" data-action="discard-reflection">放弃草稿</button></div></form></section>`:''}<section class="section-gap"><h2>已提交的复盘记录 · ${state.reflections.length} 条</h2>${state.reflections.length?state.reflections.map(r=>`<article class="card reflection-record"><span class="state-label">${r.kind==='employee'?'电子员工产物复盘':'学习复盘'} · ${escapeHTML(typeNames[r.type])}</span><h3>${escapeHTML(artifactTitle(r))}</h3><p>版本：${escapeHTML(r.version||'未提供')} · 产物 ID：${escapeHTML(r.artifactId)}${r.kind==='employee'?' · 责任岗位：'+escapeHTML(r.ownerRole||'未记录'):''}</p><p>目标：${escapeHTML(r.goal)}</p><p>结果：${escapeHTML(r.result)}</p><p>自述：${escapeHTML(r.selfStatus)} · 独立审核：未独立审核</p><p>更新时间：${escapeHTML(r.updatedAt)}</p><details><summary>证据、差距与改进详情</summary><dl>${reflectionFields.slice(1).map(([key,label])=>`<dt>${escapeHTML(label)}</dt><dd>${escapeHTML(r[key]||(key==='retestResult'?'未复验':'未记录'))}</dd>`).join('')}</dl></details><button class="outline" data-edit-reflection="${escapeHTML(r.id)}">编辑此记录</button><button class="outline" data-delete-reflection="${escapeHTML(r.id)}">删除此记录</button></article>`).join(''):'<div class="card"><p>还没有已提交复盘。选择教材、练习、作品或电子员工产物，对照目标与实际证据安排改进；允许记录证据不足和原因待确认。</p></div>'}</section>`;}
function readReflectionForm(){const form=document.getElementById('reflection-form');if(!form?.elements||!state.reflectionDraft)return state.reflectionDraft;const fields=new FormData(form),r={...state.reflectionDraft};for(const k of ['kind','type','artifactId','version','ownerRole','selfStatus',...reflectionFields.map(([k])=>k)])r[k]=fields.get(k)||'';return{...normalizeReflection(r),dirty:state.reflectionDraft.dirty};}
function captureDraft(){if(view==='reflections'&&state.reflectionDraft)state.reflectionDraft=readReflectionForm();}
function confirmDraftReplacement(){captureDraft();return !state.reflectionDraft?.dirty||typeof window.confirm!=='function'||window.confirm('当前未提交草稿将被替换。先导出可保留它；确定替换，或取消继续编辑。');}
function startReflection(type='chapter',artifactId=''){if(!confirmDraftReplacement())return;const kind=type==='deliverable'?'employee':'learning';const a=reflectionOptions(kind,type).find(a=>a.id===artifactId);state.reflectionDraft={...normalizeReflection({kind,type,artifactId,version:kind==='employee'?(a?.version||''):type==='project'?'project-draft-0.2':'sample-0.1',ownerRole:a?.role||'',goal:type==='chapter'||type==='exercise'?modules.find(m=>m.id===artifactId)?.result||'':''}),dirty:false};save();navigate('reflections','',{captureDraft:false});}
function saveReflection(){captureDraft();const r=state.reflectionDraft;if(!r)return false;const missing=['artifactId','goal','result'].find(k=>!r[k]?.trim());const feedback=document.getElementById('reflection-feedback');if(missing){feedback.textContent='未保存为记录：请填写产物、目标和实际结果。其他字段可以明确记录证据不足或未复验。';feedback.setAttribute('role','alert');const input=document.getElementById('reflection-'+missing);input?.setAttribute('aria-invalid','true');input?.focus();return false;}const now=new Date().toISOString();const record={...normalizeReflection(r),id:r.id||'reflection-'+now.replace(/\D/g,'')+'-'+Math.random().toString(36).slice(2,10),createdAt:r.createdAt||now,updatedAt:now,independentReview:'未独立审核'};const i=state.reflections.findIndex(x=>x.id===record.id);if(i===-1)state.reflections.push(record);else state.reflections[i]=record;state.reflectionDraft={...record,dirty:true};const ok=save({commitReflection:true});render();const el=document.getElementById('reflection-feedback');el.textContent=ok?'复盘记录已保存在当前浏览器；独立审核仍为未独立审核。':'保存失败：记录和输入仍在内存中；请导出全部复盘后再刷新。';el.setAttribute('role',ok?'status':'alert');return ok;}
function changeReflectionObject(target){captureDraft();const r=state.reflectionDraft;if(target.name==='kind'){r.type=r.kind==='employee'?'deliverable':'chapter';r.artifactId='';}if(target.name==='type')r.artifactId='';if(target.name==='kind'||target.name==='type'){const type=document.getElementById('reflection-type');type.innerHTML=(r.kind==='employee'?['deliverable']:['chapter','exercise','project']).map(t=>`<option value="${t}">${typeNames[t]}</option>`).join('');type.value=r.type;document.getElementById('reflection-artifactId').innerHTML='<option value="">请选择产物</option>'+reflectionOptions(r.kind,r.type).map(a=>`<option value="${escapeHTML(a.id)}">${escapeHTML(a.title)}</option>`).join('');document.getElementById('role-field').hidden=r.kind!=='employee';}if(target.name==='artifactId'||target.name==='type'||target.name==='kind'){const a=reflectionOptions(r.kind,r.type).find(a=>a.id===r.artifactId);r.version=r.kind==='employee'?(a?.version||''):r.type==='project'?'project-draft-0.2':'sample-0.1';if(r.kind==='employee')r.ownerRole=a?.role||'';document.getElementById('reflection-version').value=r.version;document.getElementById('reflection-ownerRole').value=r.ownerRole;}r.dirty=true;save();document.getElementById('reflection-feedback').textContent=storageAvailable?'草稿已保存在当前浏览器；尚未提交为记录。':'保存失败；草稿仍在内存中，可导出。';}
function markdownText(v){return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function reflectionMarkdown(){captureDraft();const records=[...state.reflections];if(state.reflectionDraft)records.push({...state.reflectionDraft,isDraft:true});return ['# 职造 · 复盘记录','网站 '+currentProductVersion+' · 当前浏览器记录；自述不等于独立审核','',...records.flatMap(r=>[`## ${r.isDraft?'当前草稿（未提交）':'记录 '+markdownText(r.id)}`,`复盘类型：${r.kind==='employee'?'电子员工产物':'学习'}；对象类型：${typeNames[r.type]}`,`产物：${markdownText(artifactTitle(r))}`,`产物标识：${markdownText(r.artifactId||'未选择')}`,`产物版本：${markdownText(r.version||'未提供')}`,`责任岗位：${markdownText(r.ownerRole||'未记录')}`,`创建时间：${markdownText(r.createdAt||'未提交')}`,`更新时间：${markdownText(r.updatedAt||'未提交')}`,`自述状态：${markdownText(r.selfStatus)}`,'独立审核状态：未独立审核',...reflectionFields.flatMap(([key,label])=>[`### ${label}`,markdownText(r[key]||(key==='retestResult'?'未复验':'未记录')),'']),'']),records.length?'':'暂无记录'].join('\n');}
function downloadMarkdown(body,name){const url=URL.createObjectURL(new Blob([body],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportReflections(){downloadMarkdown(reflectionMarkdown(),'职造-全部复盘.md');toast('已导出记录与当前草稿；请保留下载文件。');}
function unavailableProductData(){return title('PRODUCT STANDARD','标准暂不可用','没有有效门槛数据，不产生通过结论。',false)+'<p>请检查本地数据脚本是否与 index 同处 dist 目录。</p><button class="outline" data-action="reload-product-data">重新加载</button>';}
function creationPage(){if(!creationPath||!productStandard)return unavailableProductData();return title('FROM QUESTION TO PRODUCT','0→1 产品路线','职业工程能力＋创造可验证产品；七阶段不等于八门槛通过',false)+`<div class="info-banner"><strong>${escapeHTML(creationPath.title)}</strong><p>${escapeHTML(creationPath.version)} · ${escapeHTML(creationPath.status)}</p><p>当前网站版本：${currentProductVersion} · ${escapeHTML(creationPath.evaluationPolicy.currentAdvancedAssessment)}</p><p>${escapeHTML(creationPath.evaluationPolicy.distinction)}</p><p>${escapeHTML(creationPath.evaluationPolicy.thresholdPolicy)}</p></div><div class="action-row"><button class="primary" data-view="product-review">查看当前版本达标复盘</button><button class="outline" data-view="curriculum">职业能力与课程地图</button></div>${creationPath.stages.map((s,i)=>`<article class="card creation-stage" id="creation-${escapeHTML(s.id)}"><span class="state-label">第 ${i+1} 阶段 · ${escapeHTML(s.currentStatus)} · ${escapeHTML(s.formalLessonStatus)} · 专业审核${escapeHTML(s.professionalReview)}</span><h2>${escapeHTML(s.title)}</h2><h3>学习目标</h3>${listHTML(s.objectives)}<h3>提交物</h3>${listHTML(s.deliverables)}<details><summary>先修、三种评价、复盘问题与方法来源</summary><h3>先修</h3>${listHTML(s.prerequisites.map(id=>creationPath.stages.find(t=>t.id===id)?.title||id))}<dl><dt>阶段达标条件</dt><dd>${escapeHTML(s.evaluation.success)}</dd><dt>关键失败条件</dt><dd>${escapeHTML(s.evaluation.failure)}</dd><dt>证据不足</dt><dd>${escapeHTML(s.evaluation.insufficient)}</dd></dl><h3>复盘问题</h3>${listHTML(s.retrospectiveQuestions)}<h3>方法来源</h3>${s.benchmarkSourceIds.map(id=>{const b=creationPath.benchmarkSources.find(b=>b.id===id);return `<p><a href="${escapeHTML(b.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(b.title)}</a> · ${escapeHTML(b.organization)} · ${escapeHTML(b.type)} · 访问日期 ${escapeHTML(b.accessedAt)} · 发布日期 ${escapeHTML(b.publishedAt||'未知')}</p><p>${escapeHTML(b.scope)}</p><p>${escapeHTML(b.limits)}</p>`;}).join('')}</details><div class="action-row">${s.moduleIds.map(moduleLink).join('')}</div><button class="outline" data-product-stage="${escapeHTML(s.id)}">记录产品复盘</button></article>`).join('')}<section class="card section-gap"><h2>行业先进性需要实际证据</h2><p>${escapeHTML(creationPath.evaluationPolicy.advancedProductEvidence)}</p><p>${escapeHTML(creationPath.retrospectiveTemplate.rule)}</p>${listHTML(creationPath.evaluationPolicy.notEquivalent)}</section>`;}
function auditHasEvidence(e){if(typeof e==='string')return Boolean(hasKnownEvidence(e));return Array.isArray(e)&&e.some(v=>typeof v==='string'?hasKnownEvidence(v):v&&hasKnownEvidence(v.reference||v.path)&&hasKnownEvidence(v.observation||v.description));}
function validAudit(r,scope){if(!productStandard||r?.schemaVersion!=='1.0'||r.productVersion!==currentProductVersion||r.standardVersion!==productStandard.standardVersion||r.assessmentScope!==scope||(['local-mvp-0.5-textbook','local-mvp-0.6-textbook-pilot'].includes(currentProductVersion)&&(typeof textbookAuditMatches!=='function'||!textbookAuditMatches(r)))||!['formal_learning_product','static_prototype'].includes(scope)||!hasKnownEvidence(r.reviewer)||!hasKnownEvidence(r.auditedAt)||!Object.hasOwn(productStandard.conclusions,r.overall))return false;if(scope==='static_prototype')return auditHasEvidence(r.evidence);if(!Array.isArray(r.criteria)||r.criteria.length!==productStandard.gates.length)return false;const rows=r.criteria;for(const g of productStandard.gates){const matches=rows.filter(c=>c&&c.id===g.id);if(matches.length!==1||!['fail','insufficient','pass'].includes(matches[0].status)||!auditHasEvidence(matches[0].evidence))return false;}const conclusion=rows.some(c=>c.status==='fail')?'not_met':rows.some(c=>c.status==='insufficient')?'insufficient':'met_within_scope';return r.overall===conclusion;}
function matchingAudit(scope){return (Array.isArray(independentAudits?.reports)?independentAudits.reports:[]).filter(r=>validAudit(r,scope)).at(-1)||null;}
function auditEvidenceHTML(evidence){if(!evidence)return '<p>未提供执行证据</p>';const rows=Array.isArray(evidence)?evidence:[evidence];return listHTML(rows.map(e=>typeof e==='string'?e:(e.reference||e.path||'')+'：'+(e.observation||e.description||'')));}
function auditReportHTML(r){return `<p>产物版本：${escapeHTML(r.productVersion)} · 标准：${escapeHTML(r.standardVersion)}</p><p>范围：${escapeHTML(r.assessmentScopeLabel||r.assessmentScope)} · 审计人：${escapeHTML(r.reviewer||'未提供')} · 日期：${escapeHTML(r.auditedAt||'未提供')}</p><p><strong>独立结论：${escapeHTML(productStandard.conclusions[r.overall]||r.overallLabel||'证据不足')}</strong></p><p>${escapeHTML(r.decisionBasis||r.method||'')}</p>${r.criteria?.length?`<details><summary>逐门槛独立证据与后续行动</summary>${r.criteria.map(c=>`<article><h3>${escapeHTML(productStandard.gates.find(g=>g.id===c.id)?.label||c.id)} · ${escapeHTML(productStandard.gateStatuses[c.status]||'证据不足')}</h3>${auditEvidenceHTML(c.evidence)}<p>限制：${escapeHTML(c.limits||'未提供')}</p><p>差距：${escapeHTML(c.gap||'未提供')} · 责任：${escapeHTML(c.owner||'未提供')}</p><p>下一步：${escapeHTML(c.nextAction||'未提供')}</p><p>复验：${escapeHTML(c.retest?.status||'未复验')} · ${escapeHTML(c.retest?.method||'未提供')}</p></article>`).join('')}</details>`:auditEvidenceHTML(r.evidence)}${r.remainingItems?listHTML(r.remainingItems):''}${r.limits?listHTML(Array.isArray(r.limits)?r.limits:[r.limits]):''}`;}
function productAuditSection(){const formal=matchingAudit('formal_learning_product'),staticReport=matchingAudit('static_prototype');const embeddedStatic=formal?.staticVerification;const currentStatic=embeddedStatic&&embeddedStatic.productVersion===currentProductVersion&&embeddedStatic.scope==='static_prototype'&&(!['local-mvp-0.5-textbook','local-mvp-0.6-textbook-pilot'].includes(currentProductVersion)||typeof textbookAuditMatches==='function'&&textbookAuditMatches(embeddedStatic))&&auditHasEvidence(embeddedStatic.evidence)&&hasKnownEvidence(embeddedStatic.limits)&&Object.hasOwn(productStandard.conclusions,embeddedStatic.conclusion||embeddedStatic.overall)?embeddedStatic:null;const history=(Array.isArray(independentAudits?.reports)?independentAudits.reports:[]).filter(r=>r?.schemaVersion==='1.0'&&typeof r.productVersion==='string'&&(r.productVersion!==currentProductVersion||r.standardVersion!==productStandard.standardVersion));return `<div class="audit-scopes"><section class="card"><h2>正式职业学习系统：完整标准</h2>${formal?auditReportHTML(formal):`<p>当前版本未独立审计 · ${currentProductVersion}</p><p>范围：正式职业学习系统 · 标准 ${escapeHTML(productStandard.standardVersion)}。未读取匹配版本的QA报告。</p>`}<p>独立专业审核：${escapeHTML(formal?.professionalReviewStatus||'未专业审核')}</p><p>行业先进性：${escapeHTML(formal?.advancedStatus||'未验证；无可比实测与专业评审')}</p></section><section class="card"><h2>本轮本地功能：功能验收</h2>${staticReport?auditReportHTML(staticReport):currentStatic?`<p>版本：${currentProductVersion} · ${escapeHTML(currentStatic.scope||'静态功能')}</p><p>审计人：${escapeHTML(formal.reviewer)} · 日期：${escapeHTML(formal.auditedAt)}</p><p>独立功能结论：${escapeHTML(productStandard.conclusions[currentStatic.conclusion||currentStatic.overall]||'证据不足')}</p>${auditEvidenceHTML(currentStatic.evidence)}<p>限制：${escapeHTML(currentStatic.limits||'未提供')}</p>`:`<p>当前版本未独立审计 · ${currentProductVersion}</p><p>静态功能独立结论待QA交付。测试数量、旧版本报告和开发自检均不自动变为当前通过。</p>`}<p>静态范围通过不能覆盖正式系统缺口或证明职业胜任／行业先进。</p></section></div><details class="card section-gap"><summary>产品文档评估（产品经理，非QA结论）</summary><p>初始文档评估：${escapeHTML(productStandard.conclusions[productStandard.initialAssessment.conclusion])}</p><p>${escapeHTML(productStandard.initialAssessment.limitation)}</p><p>${escapeHTML(productStandard.initialAssessment.advancedStatus)}</p></details><details class="card section-gap"><summary>历史审计 · ${history.length} 份（不继承到当前版本）</summary>${history.length?history.map(a=>`<article><h3>历史版本 ${escapeHTML(a.productVersion)}</h3>${auditReportHTML(a)}</article>`).join(''):'<p>暂无历史审计</p>'}</details>`;}
function productField(key,label,value,{prefix='product',required=false,select=null}={}){const id=prefix+'-'+key,name=prefix==='baseline'?'baseline.'+key:key;return `<label for="${escapeHTML(id)}">${escapeHTML(label)}${required?'（必填）':''}</label>${select?`<select name="${escapeHTML(name)}" id="${escapeHTML(id)}">${Object.entries(select).map(([k,l])=>`<option value="${escapeHTML(k)}" ${value===k?'selected':''}>${escapeHTML(l)}</option>`).join('')}</select>`:`<textarea name="${escapeHTML(name)}" id="${escapeHTML(id)}" maxlength="12000" ${required?'required':''}>${escapeHTML(value||'')}</textarea>`}`;}
function productReviewForm(r){return `<section class="card section-gap"><h2>${r.id?'编辑产品复盘':'新建产品复盘'}</h2><p id="product-feedback" role="status">${r.dirty?'草稿未提交；已保留当前输入。':'独立QA与专业审核只读；自评不核实证据内容。'}</p><form id="product-review-form" novalidate><fieldset><legend>① 产品目标与对象</legend>${['productGoal','artifactId','artifactVersion'].map(k=>productField(k,productLabels[k],r[k],{required:true})).join('')}${productField('scope',productLabels.scope,r.scope,{select:{'':'范围待确认',...productScopes}})}${productField('stageId',productLabels.stageId,r.stageId,{select:{'':'不关联阶段',...Object.fromEntries(creationPath.stages.map(s=>[s.id,s.title]))}})}<p>标准版本：${escapeHTML(r.standardVersion)}；网站当前版本：${currentProductVersion}</p></fieldset><fieldset><legend>② 比较基线与条件</legend><p>未知字段留空或写待确认；待确认不能支撑通过。链接仅为自述线索，不证明内容真实。</p>${productStandard.benchmarkFields.map(k=>productField(k,baselineLabels[k],r.baseline[k],{prefix:'baseline',select:k==='sourceType'?{'':'未知',...sourceTypeLabels}:null})).join('')}</fieldset><fieldset><legend>③ 八门槛逐项实测证据（自述）</legend>${productStandard.gates.map(g=>{const e=r.gateEvidence[g.id];return `<section class="gate-entry"><h3>${escapeHTML(g.label)} · 必需 · 责任岗位 ${escapeHTML(g.owner)}</h3><p>${escapeHTML(g.criterion)}</p>${listHTML(g.evidenceRequired)}<p>${escapeHTML(g.staticLimit)}</p>${productField('gate.'+g.id+'.status','自述状态',e.status,{select:productStandard.gateStatuses})}${productField('gate.'+g.id+'.evidenceType','自述证据类型（不授予审核身份）',e.evidenceType,{select:Object.fromEntries(productStandard.evidenceTypes.map(t=>[t,productEvidenceTypeLabels[t]||t]))})}${productField('gate.'+g.id+'.evidence','实际证据文字或链接',e.evidence)}${productField('gate.'+g.id+'.actualResults','该门槛实际结果',e.actualResults)}</section>`;}).join('')}</fieldset><fieldset><legend>④ 改进与复验</legend>${['actualResults','gap','cause'].map(k=>productField(k,productLabels[k],r[k])).join('')}${productField('causeType','原因性质',r.causeType,{select:{fact:'有证据的事实',hypothesis:'原因假设',unknown:'待确认'}})}${['owner','nextAction','retestConditions','retestMethod','retestResult'].map(k=>productField(k,productLabels[k],r[k])).join('')}</fieldset><p id="product-decision" class="info-banner">${selfDecisionText(r)}</p><p>独立审核：未独立审核 · 专业审核：未专业审核 · 行业先进性：未验证。记录的产物版本必须有匹配独立报告才能产生独立结论。</p><div class="action-row"><button class="primary" type="submit">保存产品复盘</button><button class="outline" type="button" data-action="export-product-reviews">导出记录与当前草稿</button><button class="outline" type="button" data-action="discard-product-review">放弃产品草稿</button></div></form></section>`;}
function selfDecisionText(r){return '自评计算，仅依据填写，未核实证据：'+escapeHTML(productStandard?.conclusions[productDecision(r)]||'证据不足')+' · 范围 '+escapeHTML(productScopes[r.scope]||r.scope||'未提供')+' · 产物版本 '+escapeHTML(r.artifactVersion||'未提供')+'。不代表独立审核或行业先进。';}
function productGateCards(){const audit=matchingAudit('formal_learning_product');return '<section class="section-gap"><h2>正式系统八项必需门槛</h2>'+productStandard.gates.map(g=>{const c=audit?.criteria.find(c=>c.id===g.id);return `<article class="card product-gate-card"><h3>${escapeHTML(g.label)} · 必需 · ${escapeHTML(g.owner)}</h3><p>${escapeHTML(g.criterion)}</p>${listHTML(g.evidenceRequired)}<p>当前独立状态：${c?escapeHTML(productStandard.gateStatuses[c.status]):'当前版本待独立审计'}</p><p>${escapeHTML(g.staticLimit)}</p>${c?auditEvidenceHTML(c.evidence):''}</article>`;}).join('')+'</section>'; }
function productReviewPage(){if(!productStandard||!creationPath)return unavailableProductData();const r=state.productReviewDraft;return title('REVIEW THE ACTUAL PRODUCT','产品达标复盘','当前产品 '+currentProductVersion+' · 正式完整标准与本轮本地功能独立呈现',false)+productAuditSection()+productGateCards()+`<div class="info-banner">标准 ${escapeHTML(productStandard.standardVersion)}：${escapeHTML(productStandard.decisionRules.requiredFailure)} ${escapeHTML(productStandard.decisionRules.missingEvidence)} ${escapeHTML(productStandard.decisionRules.allPassed)}<p>${escapeHTML(productStandard.decisionRules.selfClaim)}</p><p>${escapeHTML(productStandard.decisionRules.advancedClaim)}</p></div><div class="action-row"><button class="primary" data-action="new-product-review">新建产品复盘</button><button class="outline" data-action="export-product-reviews">导出全部产品复盘（含草稿）</button><button class="outline" data-view="creation">0→1 产品路线</button></div>${r?productReviewForm(r):''}<section class="section-gap"><h2>产品自评记录 · ${state.productReviews.length} 条</h2>${state.productReviews.length?state.productReviews.map(r=>`<article class="card product-record"><h3>${escapeHTML(r.artifactId)} · ${escapeHTML(r.artifactVersion)}</h3><p>${selfDecisionText(r)}</p><p>标准：${escapeHTML(r.standardVersion)} · 更新：${escapeHTML(r.updatedAt)}</p><p>目标：${escapeHTML(r.productGoal)}</p><p>实际结果：${escapeHTML(r.actualResults||'未提供')}</p><p>独立审核：未独立审核 · 专业审核：未专业审核 · 行业先进性：未验证</p><details><summary>逐项证据、比较条件与改进行动</summary><dl>${Object.entries(r.baseline).map(([k,v])=>`<dt>${escapeHTML(baselineLabels[k]||k)}</dt><dd>${escapeHTML(v||'待确认')}</dd>`).join('')}${['stageId','gap','cause','causeType','owner','nextAction','retestConditions','retestMethod','retestResult'].map(k=>`<dt>${escapeHTML(productLabels[k])}</dt><dd>${escapeHTML(r[k]||(k==='retestResult'?'未复验':'待确认'))}</dd>`).join('')}</dl>${productStandard.gates.map(g=>`<h4>${escapeHTML(g.label)} · ${escapeHTML(productStandard.gateStatuses[r.gateEvidence[g.id].status])}</h4><p>自述证据类型：${escapeHTML(productEvidenceTypeLabels[r.gateEvidence[g.id].evidenceType]||r.gateEvidence[g.id].evidenceType)}</p><p>${escapeHTML(r.gateEvidence[g.id].evidence||'证据不足')}</p><p>${escapeHTML(r.gateEvidence[g.id].actualResults||'结果未知')}</p>`).join('')}</details><button class="outline" data-edit-product-review="${escapeHTML(r.id)}">编辑产品复盘</button><button class="outline" data-delete-product-review="${escapeHTML(r.id)}">删除此记录</button></article>`).join(''):'<div class="card"><p>尚无产品复盘。记录真实目标、版本、比较条件与八门槛证据；未知结果如实保留。</p></div>'}</section>`;}
function readProductForm(){const form=document.getElementById('product-review-form');if(!form?.elements||!state.productReviewDraft)return state.productReviewDraft;const fields=new FormData(form),r={...state.productReviewDraft,baseline:{},gateEvidence:{}};for(const k of Object.keys(productLabels))r[k]=fields.get(k)||'';for(const k of productStandard.benchmarkFields)r.baseline[k]=fields.get('baseline.'+k)||'';for(const g of productStandard.gates)r.gateEvidence[g.id]={status:fields.get('gate.'+g.id+'.status')||'insufficient',evidence:fields.get('gate.'+g.id+'.evidence')||'',actualResults:fields.get('gate.'+g.id+'.actualResults')||'',evidenceType:fields.get('gate.'+g.id+'.evidenceType')||'self_report'};return {...normalizeProductReview(r),dirty:state.productReviewDraft.dirty};}
function captureProductDraft(){if(view==='product-review'&&state.productReviewDraft)state.productReviewDraft=readProductForm();}
function confirmProductReplacement(){captureProductDraft();return !state.productReviewDraft?.dirty||typeof window.confirm!=='function'||window.confirm('当前产品草稿将被替换。先导出可保留它；确定替换，或取消继续编辑。');}
function startProductReview(stageId=''){if(!productStandard||!creationPath||!confirmProductReplacement())return;const stage=creationPath.stages.find(s=>s.id===stageId);state.productReviewDraft={...normalizeProductReview({standardVersion:productStandard.standardVersion,stageId:stage?.id||'',scope:stage?'learner_product':'formal_learning_product',productGoal:stage?.objectives.join('；')||''}),dirty:false};save();navigate('product-review','',{captureDraft:false});}
function saveProductReview(){captureProductDraft();const r=state.productReviewDraft;if(!r||!productStandard)return false;const missing=['productGoal','artifactId','artifactVersion','scope'].find(k=>!hasKnownEvidence(r[k]));const feedback=document.getElementById('product-feedback');if(missing){feedback.textContent='未保存：请填写产品目标、产物 ID、产物版本及明确评价范围。证据未知可以保留，不自动通过。';feedback.setAttribute('role','alert');const field=document.getElementById('product-'+missing);field?.setAttribute('aria-invalid','true');field?.focus();return false;}const now=new Date().toISOString(),record={...normalizeProductReview(r),id:r.id||'product-review-'+now.replace(/\D/g,'')+'-'+Math.random().toString(36).slice(2,10),createdAt:r.createdAt||now,updatedAt:now};const idx=state.productReviews.findIndex(a=>a.id===record.id);if(idx===-1)state.productReviews.push(record);else state.productReviews[idx]=record;state.productReviewDraft={...record,dirty:true};const ok=save({commitProductReview:true});render();const el=document.getElementById('product-feedback');el.textContent=ok?'产品复盘已保存在当前浏览器；独立与专业审核没有改变。':'保存失败：记录仍在内存中，请导出全部产品复盘后再刷新／关闭。';el.setAttribute('role',ok?'status':'alert');return ok;}
function onProductInput(target){captureProductDraft();if(!state.productReviewDraft)return;state.productReviewDraft.dirty=true;target?.removeAttribute?.('aria-invalid');save();document.getElementById('product-feedback').textContent=storageAvailable?'产品草稿已在本浏览器保存，尚未提交记录。':'保存失败：输入保留，可导出当前草稿。';document.getElementById('product-decision').innerHTML=selfDecisionText(state.productReviewDraft);}
function productReviewMarkdown(){captureProductDraft();const records=[...state.productReviews];if(state.productReviewDraft)records.push({...state.productReviewDraft,isDraft:true});return ['# 职造 · 产品达标复盘',`网站当前版本：${currentProductVersion}`,'自评仅依据填写，证据未核实；链接不证明真实。独立审核未独立审核，专业审核未专业审核，行业先进性未验证。','',...records.flatMap(r=>[`## ${r.isDraft?'当前产品草稿（未提交）':'记录 '+markdownText(r.id)}`,`标准版本：${markdownText(r.standardVersion)}`,`创建时间：${markdownText(r.createdAt||'未提交')}`,`更新时间：${markdownText(r.updatedAt||'未提交')}`,`自评计算：${productStandard?.conclusions[productDecision(r)]||'证据不足'}；范围 ${markdownText(r.scope)}；产物版本 ${markdownText(r.artifactVersion||'未提供')}`,...Object.keys(productLabels).flatMap(k=>[`### ${productLabels[k]}`,markdownText(r[k]||(k==='retestResult'?'未复验':'待确认')),'']),'### 比较基线',...Object.entries(r.baseline).map(([k,v])=>`${baselineLabels[k]||k}：${markdownText(v||'待确认')}`),'### 门槛自述证据',...(productStandard?.gates||[]).flatMap(g=>{const e=r.gateEvidence[g.id]||{};return [`#### ${g.id} · ${g.label}`,`自述状态：${productStandard.gateStatuses[e.status]||'证据不足'}`,`自述证据类型：${markdownText(e.evidenceType||'self_report')}`,`证据：${markdownText(e.evidence||'证据不足')}`,`实际结果：${markdownText(e.actualResults||'结果未知')}`,''];}),'独立审核状态：未独立审核','专业审核状态：未专业审核','行业先进性：未验证',''])].join('\n');}
function exportProductReviews(){downloadMarkdown(productReviewMarkdown(),'职造-产品达标复盘.md');toast('已导出产品记录与草稿；证据及结论为自评。');}
function render(){if(typeof LearningWorkbench!=='undefined')LearningWorkbench.beforeRender();if(typeof generationUnmount==='function')generationUnmount();if(document.getElementById('side-level'))document.getElementById('side-level').textContent=levelNames[state.profile.level];document.getElementById('breadcrumb').innerHTML='学习空间 <span>/</span> '+labels[view];document.querySelectorAll('nav button').forEach(b=>{const active=b.dataset.view===(['review','check'].includes(view)?'questions':view==='projects'?'records':view==='path'?'learn':view);b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});app.innerHTML=(typeof LearningExperienceV13!=='undefined'&&LearningExperienceV13.handles(view)?LearningExperienceV13.page(view):({home:()=>LearningWorkbench.page('home'),path:()=>LearningWorkbench.page('path'),learn:()=>LearningWorkbench.page('learn'),records:()=>LearningWorkbench.page('records'),projects:()=>LearningWorkbench.page('projects'),'history-home':home,'history-path':pathPage,'projects-history':projectsPage,book:bookPage,standards:standardsPage,curriculum:curriculumPage,reflections:reflectionsPage,sources:sourcesPage,creation:creationPage,'product-review':productReviewPage,generation:typeof generationPage==='function'?generationPage:()=>'<h1>单章生成资源未加载</h1>'}[view])());updateSaveStatus();if(typeof LearningWorkbench!=='undefined')LearningWorkbench.mount(view);if(typeof LearningExperienceV13!=='undefined')LearningExperienceV13.mount(view);if(view==='generation'&&typeof generationMount==='function')generationMount();}
function focusTitle(){const node=selectedModule&&view==='curriculum'?document.getElementById('module-title-'+selectedModule):app.querySelector('h1');node?.setAttribute('tabindex','-1');node?.focus({preventScroll:true});if(selectedModule&&view==='curriculum')node?.scrollIntoView?.({block:'start'});else window.scrollTo({top:0,behavior:'auto'});}
function navigate(v,target='',options={}){if(!Object.keys(labels).includes(v))return;if(view==='generation'&&v!==view&&typeof generationCanLeave==='function'&&!generationCanLeave())return;if(options.captureDraft!==false){captureDraft();captureProductDraft();}if(view==='product-review'&&v!=='product-review'&&state.productReviewDraft?.dirty&&typeof window.confirm==='function'&&!window.confirm('产品复盘尚未提交。草稿将保留；确定离开，或取消继续编辑。保存失败请先导出。'))return;if(view==='reflections'&&v!=='reflections'&&state.reflectionDraft?.dirty&&typeof window.confirm==='function'&&!window.confirm('复盘尚未提交为记录。草稿将保留；确定离开，或取消继续编辑。保存失败时请先导出。'))return;view=v;if(v==='book'&&modules.some(m=>m.id===target))selected=target;selectedModule=v==='curriculum'&&curriculum?.modules.some(m=>m.id===target)?target:'';quizChoice=null;quizResult=null;let hash='#'+v+(selectedModule?'/'+selectedModule:'');if(v==='book'){if(options.legacy){if(typeof textbookSetLocation==='function')textbookSetLocation({target:'sample'});hash='#book/sample/'+selected;}else{if(typeof textbookSetLocation==='function')textbookSetLocation({target:'agent',chapter:options.textbookChapter||'c01',source:options.textbookSource||'current'});hash='#book/agent'+(options.textbookChapter?'/'+options.textbookChapter:'')+(options.textbookSource==='v05'?'/original':'');}}history.pushState(null,'',hash);render();focusTitle();}
let profileTrigger=null;
function openProfile(){profileTrigger=typeof document.activeElement==='object'?document.activeElement:null;const d=document.getElementById('onboarding');document.getElementById('level').value=state.profile.level;document.getElementById('goal').value=state.profile.goal;document.getElementById('hours').value=state.profile.hours;document.getElementById('hours-output').textContent=state.profile.hours;d.showModal();document.getElementById('level').focus();}
let toastTimer;function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.productStage){startProductReview(b.dataset.productStage);return}if(b.dataset.action==='new-product-review'){startProductReview();return}if(b.dataset.action==='export-product-reviews'){exportProductReviews();return}if(b.dataset.action==='reload-product-data'){if(typeof location.reload==='function')location.reload();return}if(b.dataset.action==='discard-product-review'){if(typeof window.confirm==='function'&&!window.confirm('放弃当前产品草稿？已提交的记录保留。'))return;state.productReviewDraft=null;save();render();focusTitle();return}if(b.dataset.editProductReview){if(!confirmProductReplacement())return;const r=state.productReviews.find(r=>r.id===b.dataset.editProductReview);if(r){state.productReviewDraft={...r,dirty:false};save();render();document.getElementById('product-productGoal').focus();}return}if(b.dataset.deleteProductReview){const id=b.dataset.deleteProductReview;if(!state.productReviews.some(r=>r.id===id))return;if(typeof window.confirm==='function'&&!window.confirm('删除此产品复盘？其他记录保留，建议先导出。'))return;state.productReviews=state.productReviews.filter(r=>r.id!==id);if(state.productReviewDraft?.id===id)state.productReviewDraft=null;save();render();focusTitle();return}if(b.dataset.view){navigate(b.dataset.view);return}if(b.dataset.module){navigate('curriculum',b.dataset.module);return}if(b.dataset.lesson){if(!modules.some(m=>m.id===b.dataset.lesson))return;selected=b.dataset.lesson;state.lastLesson=selected;save();navigate('book',selected,{legacy:true});return}if(b.dataset.reflect){startReflection(b.dataset.reflect,b.dataset.artifact);return}if(b.dataset.deleteReflection){const id=b.dataset.deleteReflection;const r=state.reflections.find(r=>r.id===id);if(!r)return;if(typeof window.confirm==='function'&&!window.confirm('删除这条复盘记录？其他记录会保留；建议先导出。'))return;state.reflections=state.reflections.filter(r=>r.id!==id);if(state.reflectionDraft?.id===id)state.reflectionDraft=null;save();render();focusTitle();return}if(b.dataset.editReflection){if(!confirmDraftReplacement())return;const r=state.reflections.find(r=>r.id===b.dataset.editReflection);if(r){state.reflectionDraft={...r,dirty:false};save();render();document.getElementById('reflection-goal').focus();}return}if(b.dataset.action==='new-reflection'){startReflection();return}if(b.dataset.action==='export-reflections'){exportReflections();return}if(b.dataset.action==='discard-reflection'){if(typeof window.confirm==='function'&&!window.confirm('放弃当前草稿？已提交的记录会保留。'))return;state.reflectionDraft=null;save();render();focusTitle();return}if(b.dataset.choice!==undefined){const c=Number(b.dataset.choice);if(!Number.isInteger(c)||c<0||c>2)return;quizChoice=c;quizResult=null;const scroll=window.scrollY;render();window.scrollTo(0,scroll);app.querySelector(`[data-choice="${quizChoice}"]`).focus({preventScroll:true});return}if(b.dataset.action==='profile'||b.id==='profile-open'){openProfile();return}if(b.id==='close-profile'){document.getElementById('onboarding').close();profileTrigger?.focus();return}if(b.dataset.action==='quiz'){if(quizChoice===null)return;const m=modules.find(m=>m.id===selected);quizResult=quizChoice===m.lesson.answer;if(quizResult&&!state.passed.includes(m.id)){state.passed.push(m.id);save()}const scroll=window.scrollY;render();window.scrollTo(0,scroll);app.querySelector('[data-action="quiz"]').focus({preventScroll:true});return}if(b.dataset.saveNote){const id=b.dataset.saveNote;if(!projects.some(p=>p.id===id))return;state.notes[id]=textValue(document.getElementById('note-'+id).value);save();toast(storageAvailable?'实践记录已保存在当前浏览器。':'保存失败，请导出学习计划。');return}if(b.id==='export')exportPlan();});
document.addEventListener('change',e=>{const input=e.target;if(input.closest?.('#product-review-form')){onProductInput(input);return;}if(input.closest?.('#reflection-form')){if(['kind','type','artifactId'].includes(input.name))changeReflectionObject(input);else {captureDraft();state.reflectionDraft.dirty=true;save();}return;}if(input.dataset.project){const id=input.dataset.project,p=projects.find(p=>p.id===id),i=Number(input.dataset.check);if(!p||!Number.isInteger(i)||i<0||i>=p.checks.length)return;const list=Array.isArray(state.checks[id])?state.checks[id]:[];state.checks[id]=input.checked?[...new Set([...list,i])]:list.filter(x=>x!==i);document.querySelectorAll('[data-note]').forEach(t=>state.notes[t.dataset.note]=textValue(t.value));save();const scroll=window.scrollY;render();window.scrollTo(0,scroll);app.querySelector(`[data-project="${id}"][data-check="${i}"]`).focus({preventScroll:true});}});
document.addEventListener('input',e=>{if(e.target.closest?.('#product-review-form')){onProductInput(e.target);return;}if(e.target.closest?.('#reflection-form')){captureDraft();state.reflectionDraft.dirty=true;e.target.removeAttribute('aria-invalid');save();document.getElementById('reflection-feedback').textContent=storageAvailable?'草稿已保存在当前浏览器；尚未提交为记录。':'保存失败；输入仍保留，可导出当前草稿。';return;}if(e.target.dataset.note&&projects.some(p=>p.id===e.target.dataset.note)){state.notes[e.target.dataset.note]=textValue(e.target.value);save();}});
document.addEventListener('submit',e=>{if(e.target.id==='product-review-form'){e.preventDefault();saveProductReview();return;}if(e.target.id==='reflection-form'){e.preventDefault();saveReflection();}});
document.getElementById('hours').addEventListener('input',e=>document.getElementById('hours-output').textContent=e.target.value);
document.getElementById('onboarding').addEventListener('close',()=>profileTrigger?.focus());
document.getElementById('profile-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);state.profile={level:levelNames[f.get('level')]?f.get('level'):'beginner',goal:goalNames[f.get('goal')]?f.get('goal'):'career',hours:Math.min(20,Math.max(3,Number(f.get('hours'))||8))};selected=nextModule().id;state.lastLesson=selected;save();document.getElementById('onboarding').close();navigate('history-path');toast('已按旧版档案组合历史学习路线。');});
function exportPlan(){const body=['# 职造 · Agent 开发者学习计划','',`学习起点：${levelNames[state.profile.level]}`,`学习目标：${goalNames[state.profile.goal]}`,`每周投入：${state.profile.hours} 小时`,`建议学习周期：${Math.ceil(plannedHours()/state.profile.hours)} 周（参考估算）`,'','本计划由预设模板组合，非实时 AI 生成。测验通过不代表职业能力认证。','',...route().flatMap((m,i)=>[`## ${i+1}. ${m.title}`,`预计 ${m.hours} 小时 · ${state.passed.includes(m.id)?'概念测验通过':'待学习'}`,m.result,'',m.lesson.title,m.lesson.intro,m.lesson.concept,'',`练习：${m.lesson.exercise}`,'']),...projects.flatMap(p=>[`## 项目：${p.title}`,p.desc,...p.checks.map((c,i)=>`- [${(Array.isArray(state.checks[p.id])?state.checks[p.id]:[]).includes(i)?'x':' '}] ${c}`),`实践记录：${markdownText(textValue(state.notes[p.id])||'未填写')}`,'']),'## 官方参考资料',...sources.map(s=>`- ${s.title}: ${s.url}`),'','短教材示例 sample-0.1 · 原型资料标签日期 2026-10-10（未逐条核验）','课程地图 curriculum-draft-0.2：规划覆盖不代表完整教材或职业达标。'].join('\n');downloadMarkdown(body,'Agent开发者-学习计划.md');toast('学习计划已导出。');}
function restoreLocation(){captureDraft();captureProductDraft();const loc=readLocation();view=loc.view;if(view==='book'){selected=loc.target==='sample'&&modules.some(m=>m.id===loc.chapter)?loc.chapter:modules.some(m=>m.id===loc.target)?loc.target:state.lastLesson;if(typeof textbookSetLocation==='function')textbookSetLocation(loc);}selectedModule=view==='curriculum'&&curriculum?.modules.some(m=>m.id===loc.target)?loc.target:'';quizChoice=null;quizResult=null;render();focusTitle();}
window.addEventListener('hashchange',restoreLocation);window.addEventListener('popstate',restoreLocation);
window.addEventListener('beforeunload',e=>{if(persistencePending||(typeof generationHasDraft==='function'&&generationHasDraft())){e.preventDefault();e.returnValue='';}});
render();
